const lockGoodsDelivery = `-- name: LockGoodsDelivery :one
SELECT order_id, provider_slug, idempotency_key, provider_reference, status, attempt_count, next_attempt_at, failure_class, last_error_code, refund_ledger_transaction_id, created_at, updated_at, delivered_at FROM goods_deliveries WHERE order_id = $1 FOR UPDATE
`

// Taken before every provider submission. Two workers racing on one order
// serialise here, and the loser re-reads a row that is already submitted.
func (q *Queries) LockGoodsDelivery(ctx context.Context, orderID pgtype.UUID) (GoodsDelivery, error) {
	row := q.db.QueryRow(ctx, lockGoodsDelivery, orderID)
	var i GoodsDelivery
	err := row.Scan(
		&i.OrderID,
		&i.ProviderSlug,
		&i.IdempotencyKey,
		&i.ProviderReference,
		&i.Status,
		&i.AttemptCount,
		&i.NextAttemptAt,
		&i.FailureClass,
		&i.LastErrorCode,
		&i.RefundLedgerTransactionID,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.DeliveredAt,
	)
	return i, err
}

