const searchGoodsOrders = `-- name: SearchGoodsOrders :many
SELECT
  g.order_id, g.user_id, g.product_id, g.quantity, g.recipient_username, g.recipient_is_self, g.quoted_cost_minor, g.quoted_price_minor, g.currency, g.quote_expires_at, g.status, g.created_at, g.updated_at,
  d.status AS delivery_status,
  d.attempt_count AS delivery_attempts,
  d.failure_class AS delivery_failure_class,
  d.last_error_code AS delivery_error_code,
  d.delivered_at,
  d.refund_ledger_transaction_id
FROM goods_orders g
LEFT JOIN goods_deliveries d ON d.order_id = g.order_id
WHERE (
    $1::timestamptz IS NULL
    OR (g.created_at, g.order_id) < ($1::timestamptz, $2::uuid)
  )
  AND ($3::text IS NULL OR g.status = $3)
  AND ($4::uuid IS NULL OR g.user_id = $4)
ORDER BY g.created_at DESC, g.order_id DESC
LIMIT $5
`

type SearchGoodsOrdersParams struct {
	CursorCreatedAt pgtype.Timestamptz `json:"cursor_created_at"`
	CursorID        pgtype.UUID        `json:"cursor_id"`
	Status          pgtype.Text        `json:"status"`
	UserID          pgtype.UUID        `json:"user_id"`
	PageSize        int32              `json:"page_size"`
}

type SearchGoodsOrdersRow struct {
	GoodsOrder                GoodsOrder         `json:"goods_order"`
	DeliveryStatus            pgtype.Text        `json:"delivery_status"`
	DeliveryAttempts          pgtype.Int4        `json:"delivery_attempts"`
	DeliveryFailureClass      pgtype.Text        `json:"delivery_failure_class"`
	DeliveryErrorCode         pgtype.Text        `json:"delivery_error_code"`
	DeliveredAt               pgtype.Timestamptz `json:"delivered_at"`
	RefundLedgerTransactionID pgtype.UUID        `json:"refund_ledger_transaction_id"`
}

// Delivery columns are selected individually because an order that was never
// paid has no delivery row, and an embedded struct cannot hold that absence.
func (q *Queries) SearchGoodsOrders(ctx context.Context, arg SearchGoodsOrdersParams) ([]SearchGoodsOrdersRow, error) {
	rows, err := q.db.Query(ctx, searchGoodsOrders,
		arg.CursorCreatedAt,
		arg.CursorID,
		arg.Status,
		arg.UserID,
		arg.PageSize,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SearchGoodsOrdersRow{}
	for rows.Next() {
		var i SearchGoodsOrdersRow
		if err := rows.Scan(
			&i.GoodsOrder.OrderID,
			&i.GoodsOrder.UserID,
			&i.GoodsOrder.ProductID,
			&i.GoodsOrder.Quantity,
			&i.GoodsOrder.RecipientUsername,
			&i.GoodsOrder.RecipientIsSelf,
			&i.GoodsOrder.QuotedCostMinor,
			&i.GoodsOrder.QuotedPriceMinor,
			&i.GoodsOrder.Currency,
			&i.GoodsOrder.QuoteExpiresAt,
			&i.GoodsOrder.Status,
			&i.GoodsOrder.CreatedAt,
			&i.GoodsOrder.UpdatedAt,
			&i.DeliveryStatus,
			&i.DeliveryAttempts,
			&i.DeliveryFailureClass,
			&i.DeliveryErrorCode,
			&i.DeliveredAt,
			&i.RefundLedgerTransactionID,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

