const sumRecentGoodsSpend = `-- name: SumRecentGoodsSpend :one
SELECT COALESCE(sum(g.quoted_cost_minor), 0)::bigint
FROM goods_orders g
JOIN goods_deliveries d ON d.order_id = g.order_id
JOIN goods_products p ON p.id = g.product_id
WHERE p.provider_slug = $1
  AND d.status IN ('submitted', 'delivered')
  AND d.created_at >= now() - $2::interval
`

type SumRecentGoodsSpendParams struct {
	ProviderSlug string          `json:"provider_slug"`
	Lookback     pgtype.Interval `json:"lookback"`
}

// Provider cost, not customer price: the spend ceiling protects the operator's
// funding source, and that is what the provider actually draws down.
func (q *Queries) SumRecentGoodsSpend(ctx context.Context, arg SumRecentGoodsSpendParams) (int64, error) {
	row := q.db.QueryRow(ctx, sumRecentGoodsSpend, arg.ProviderSlug, arg.Lookback)
	var column_1 int64
	err := row.Scan(&column_1)
	return column_1, err
}

